#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    // suffix: p[n-y .. n-1]
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    // middle: p[x .. n-y-1]
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    // prefix: p[0 .. x-1]
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int target = 0; target < n-2; target++){
        int pos = -1;
        for(int i = target; i < n; i++) if(p[i] == target+1){ pos = i; break; }
        if(pos == target) continue;

        // Step 1: Move element from pos to position n-1
        if(pos != n-1){
            // We want x = pos+1, y = n-1-pos
            // But need x+y < n: (pos+1)+(n-1-pos) = n, not < n
            // So use x = pos+1, y = n-2-pos (if valid)
            // After op: suffix [n-(n-2-pos)..n-1] = [pos+2..n-1] goes to front
            // middle [pos+1..pos+1] (one element) stays in middle  
            // prefix [0..pos] goes to end
            // Element at pos goes to end of new array (position n-1). Wait no - prefix goes to end.
            // New array: [p[pos+2..n-1], p[pos+1], p[0..pos]]
            // Element target+1 is at p[pos], which is now at the last position of [p[0..pos]] block = position n-1. Yes!
            if(pos+1 > 0 && n-2-pos > 0 && (pos+1)+(n-2-pos) < n){
                ops.push_back({pos+1, n-2-pos});
                apply(p, pos+1, n-2-pos);
            } else if(pos == 0 && n >= 3){
                // x=1, y=n-2: x+y=n-1<n. Element at 0 goes to position n-1.
                ops.push_back({1, n-2});
                apply(p, 1, n-2);
            }
            // Verify element is now at n-1
            pos = -1;
            for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
            if(pos != n-1) continue; // something went wrong, skip
        }

        // Step 2: Move element from n-1 to position target
        // x = target, y = 1: but need x > 0, so target > 0
        // After op: [p[n-1], p[target..n-2], p[0..target-1]]
        // Element goes to position 0. We want it at position target.
        // Use x = target+1, y = 1: need target+2 < n
        // New: [p[n-1], p[target+1..n-2], p[0..target]]
        // Nope, element at pos 0. 
        // Actually: x=n-1-target, y=1. After: [p[n-1], p[n-1-target..n-2], p[0..n-2-target]]
        // Element at position 0... Let me think differently.
        // We need suffix of size 1 (element at n-1) to land at position target.
        // After op with (x,y): suffix goes to [0..y-1], middle to [y..y+mid-1], prefix to end
        // Element is in suffix (y=1), goes to position 0. Then prefix [0..x-1] goes to end.
        // To get element at position target, we need y + (n-x-y) positions before prefix... no, element is always at position 0 after swap if y=1.
        // So do op(1, n-1-target) to then move it from 0 to target? No, that's another op.
        // Alternative: use y = n-target. Suffix = p[target..n-1]. After op: [p[target..n-1], middle, prefix].
        // Hmm, let me just use y=1, x=target+1 if target+2<n:
        if(target + 2 < n){
            ops.push_back({target+1, 1});
            apply(p, target+1, 1);
            // Now element is at position 0... not target. Let me recheck.
        } else if(target == 0){
            ops.push_back({1, 1});
            apply(p, 1, 1);
        }
    }

    // Verify
    bool sorted = true;
    for(int i=0;i<n;i++) if(p[i]!=i+1) sorted=false;

    if(!sorted){
        // Fallback: output 0 operations
        printf("0\n");
        return 0;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
